export function cappedRunningTotal(nums, cap) {
  const result = [];
  let total = 0;
  let capped = false;

  for (let i = 0; i < nums.length; i++) {
    if (!capped) {
      total += nums[i];
      if (total >= cap) {
        total = cap;
        capped = true;
      }
    }
    result.push(total);
  }

  return result;
}
